#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# Copyright (c) 2025-2026 Val Melamed

# Validates that all commit messages in a range follow Conventional Commits format.
# Used in CI to enforce commit message discipline.

set -euo pipefail

script_name=$(basename "${BASH_SOURCE[0]}")
script_dir=$(dirname "$(realpath -e "${BASH_SOURCE[0]}")")
lib_dir=$(realpath -e "$script_dir/../../scripts/bash/lib")

declare -xr script_name
declare -xr script_dir
declare -xr lib_dir

# vm2 core lib
source "$lib_dir/gh_core.sh"

# vm2 core lib exit codes
declare -xri err_argument_value

# vm2 core lib constants
declare -xr check_em
declare -xra allowed_commit_types

# vm2 core lib variables
declare -x _ignore

# this script's components
source "$script_dir/validate-commits.usage.sh"
source "$script_dir/validate-commits.args.sh"

declare -x base_ref

# this script's arguments
get_arguments "$@"
declare -xr repo_path
declare -xr base_ref

# Build the type alternation: feat|fix|perf|...
ifs=$IFS
IFS='|' types_pattern="${allowed_commit_types[*]}"
IFS=$ifs

# Conventional Commits: type[(scope)][!]: description
readonly cc_regex="^($types_pattern)(\(.+\))?!?: .+"

# Get all commit hashes and subjects in the range
declare -i bad=0
declare -a bad_hashes=()
declare -a bad_subjects=()
declare hash subject
while IFS=$'\t' read -r hash subject; do
    # Skip "Merge..." and "Revert..." commit messages generated by git
    [[ ! "$subject" =~ ^(Merge|Revert)\  ]] || continue

    if [[ ! "${subject,,}" =~ $cc_regex ]]; then
        error -ns "Bad commit message: ${hash:0:8} $subject"
        bad_hashes+=("$hash")
        bad_subjects+=("$subject")
        (( ++bad ))
    fi
done < <(git -C "$repo_path" log --format=$'%H\t%s' "$base_ref..HEAD")  # ends with a newline and is safe for read without [[ -n $_line ]] guard

if (( bad > 0 )); then
    branch=$(git -C "$repo_path" branch --show-current)
    # In CI the PR merge ref is checked out with a detached HEAD, so there is no current branch: fall back to the PR's
    # source branch (set by the runner on pull_request events), or a placeholder for a local detached HEAD.
    [[ -n $branch ]] || branch=${GITHUB_HEAD_REF:-<your-branch>}
    # With --repo-dir the validated repository may not be the current directory, and the suggested commands run in the
    # caller's terminal: tell them to change to it first.
    declare -a cd_hint=()
    [[ $(realpath "$repo_path") == "$(realpath "$PWD")" ]] || cd_hint=("  cd $(printf '%q' "$(realpath "$repo_path")")")
    # The oldest offending commit's parent is the tightest rebase start point that still
    # surfaces every bad commit in the todo list -- no need to go back to $base_ref itself.
    oldest_bad_parent="${bad_hashes[-1]}^"
    echo "" >&2
    info "Expected format: <type>[(scope)][!]: <description>" \
         "Allowed types:   ${allowed_commit_types[*]}" \
         "Examples:       chore(dependencies): update dependencies and lock files"
    info "To fix, copy and paste in your terminal:" \
         "${cd_hint[@]}" \
         "  git rebase -i $oldest_bad_parent" \
         "Then, in the editor, change 'pick' to 'reword' for each commit listed below, save and close." \
         "Git opens the message editor for that commit; edit it (e.g. prepend '<type>: '), save and close." \
         "Commits needing reword ($bad):"
    declare -i i
    for (( i = 0; i < ${#bad_hashes[@]}; i++ )); do
        info "  ${bad_hashes[$i]:0:8}  ${bad_subjects[$i]}"
    done
    info "Note: rebase rewrites commit hashes from $oldest_bad_parent to HEAD." \
         "Repeat reword for each commit above in the same rebase session, then force-push:" \
         "  git push --force-with-lease origin $branch"
    exit "$err_argument_value"
fi

info "$check_em All commit messages follow Conventional Commits format"
